create or replace function public.veterans_normalize_email(value text) returns text language sql immutable set search_path=pg_catalog,public as $$ select lower(trim(coalesce(value,''))) $$;
create or replace function public.veterans_current_user_email() returns text language sql stable set search_path=pg_catalog,public as $$ select public.veterans_normalize_email(auth.jwt()->>'email') $$;
drop policy if exists veterans_products_read on public.veterans_products;create policy veterans_products_public_read on public.veterans_products for select to anon,authenticated using(active=true);create policy veterans_products_admin_read on public.veterans_products for select to authenticated using(public.veterans_is_active_admin());
revoke execute on function public.veterans_is_active_admin() from public,anon;revoke execute on function public.veterans_is_owner() from public,anon;grant execute on function public.veterans_is_active_admin() to authenticated;grant execute on function public.veterans_is_owner() to authenticated;
